(function () {
  "use strict";

  var ROUND_KEYS = ["r1", "r2", "r3", "r4", "r5"];
  var ROUND_LABELS = { r1: "Round 1", r2: "Round 2", r3: "Round 3", r4: "Round 4", r5: "Round 5" };
  var ROUND_LOGO_URI = "data:image/png;base64,";
  var ROUND_NAMES = [
    { name: "The Lab", day: "Day 1" },
    { name: "The Lost Signal", day: "Day 1" },
    { name: "The Christmas Lights", day: "Day 1" },
    { name: "The Upside Down", day: "Day 2" },
    { name: "Escape the Upside Down", day: "Day 2" }
  ];
  var ROUND_INFO = ROUND_KEYS.map(function (k, i) {
    return { key: k, title: ROUND_LABELS[k], name: ROUND_NAMES[i].name, day: ROUND_NAMES[i].day, num: i + 1 };
  });

  var seedTeams = [
    { id: "seed-t1", name: "RtR", members: ["Saksham Singh", "Vasundhara Namdeo", "Sagar Pratap Sin", "Lakshita Bisen"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t2", name: "Doom", members: ["Nitin Yadav", "Prateek", "Krishn Tomar", "Parth Devedi"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t3", name: "Silicon Synergy", members: ["Sanskar Agrawal", "Shivani Mangal", "Yogesh Sharma", "Mohit Goyal"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t4", name: "Vecna", members: ["Anushka Jadon", "Annu Sharma", "Aanchal Gautam", "Akshat Sakhiya"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t5", name: "Nexus", members: ["Anushree Khatri", "Akshta Gupta", "Aadya Goyal", "Suraj Sharma"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t6", name: "Chulbule bhature", members: ["Vandana Rana", "Urvashi Singh", "Shrshti Yadav", "Utkarsh Pandey"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t7", name: "TEAM ROCKET", members: ["Prabhanshu Tiwari", "Yashraj Soni", "Lavansh Sahu", "Prateek Ladkani"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t8", name: "Dhurandhar", members: ["Shreya Yadav", "Ojaswi Tiwari", "Tanvi Saxena", "Mohin Chauhan"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t9", name: "Solder squad", members: ["Sakshi Gour", "Vinisha Pandey", "Richa Verma", "Mandvi Rathore"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t10", name: "Squad 011", members: ["Mandvi Yadav", "Mansi Sharda", "Poonam Jiwanar", "Priyadarshni Cha"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t11", name: "Akatsuki", members: ["Himesh", "Abhishek Balbasaur", "Atharva Vaidhya", "Abhiraj"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t12", name: "No signal", members: ["Yash Dwivedi", "Sanskrati Gupta", "Somya Sharma", "Lalita Sharma"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t13", name: "The Og's", members: ["Monali Shakya", "Mohini Chauhan", "Arana Khan", "Arpita Chauhan"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t14", name: "Kuch bhi", members: ["Mradul", "Abhishek Bajoriy", "Animay Jain"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t15", name: "HACKSMITH", members: ["Vanshika Golandaj", "Tanish Mehra", "Saransh Kachole", "Kush Jadwani"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t16", name: "Team Tappu Potato", members: ["Chirag Sharma", "Harsh Kushwah", "Hritik Agrawal", "Harshit Jha"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t17", name: "Electropulse", members: ["Vivek Kushwah", "Pranav Sharma", "Somya Dandotiy", "Uma Sharma"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t18", name: "Cyber Aura", members: ["Abeer Nimonkar", "Aditya Mudgal", "Abhay Singh Tor", "Aditya Gupta"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t19", name: "POWER RANGERS", members: ["Krishna Agrawal", "Harshit Bagri", "Deeksha Gupta", "Krishna Patharol"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t20", name: "BRAZZERS", members: ["Jayant Jagdev", "Devansh Kumar Karad", "Yash Sonawa", "Arinjay Baghel"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } },
    { id: "seed-t21", name: "No cap crew", members: ["Manvi Tyagi", "Yashvi Singh", "Samarth Mitra", "Raj Tyagi"], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } }
  ];

  var teams = seedTeams.map(function (t) { return Object.assign({}, t, { marks: Object.assign({}, t.marks) }); });
  var filter = "all";

  function totalOf(t) {
    var s = 0;
    ROUND_KEYS.forEach(function (k) { s += Number((t.marks || {})[k]) || 0; });
    return s;
  }

  function ranked() {
    return teams
      .map(function (t) { return Object.assign({}, t, { total: totalOf(t) }); })
      .sort(function (a, b) { return b.total - a.total; })
      .map(function (t, i) { return Object.assign({}, t, { rank: i + 1 }); });
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function uid() { return "up-" + Math.random().toString(36).slice(2, 9); }

  // ---------- Tabs ----------
  document.querySelectorAll(".zn-tab").forEach(function (btn) {
    btn.addEventListener("click", function () {
      document.querySelectorAll(".zn-tab").forEach(function (b) { b.classList.remove("zn-tab-active"); });
      document.querySelectorAll(".zn-view").forEach(function (v) { v.classList.remove("zn-view-active"); });
      btn.classList.add("zn-tab-active");
      document.getElementById("view-" + btn.dataset.tab).classList.add("zn-view-active");
    });
  });

  // ---------- Rounds (static) ----------
  var roundsGrid = document.getElementById("roundsGrid");
  roundsGrid.innerHTML = ROUND_INFO.map(function (r) {
    return '<div class="zn-roundcard"><div class="zn-roundday">' + esc(r.day) + '</div><div class="zn-roundnum"><img src="' + ROUND_LOGO_URI + '" alt="Round ' + r.num + '"></div><h3>' + esc(r.title) + '</h3><p>' + esc(r.name) + '</p></div>';
  }).join("");

  // ---------- Leaderboard ----------
  var filterBar = document.getElementById("filterBar");
  var customN = document.getElementById("customN");
  var syncPill = document.getElementById("syncPill");

  function setSyncLabel(text, live) {
    if (!syncPill) return;
    syncPill.textContent = text;
    syncPill.classList.toggle("zn-save-live", !!live);
  }

  filterBar.addEventListener("click", function (e) {
    var f = e.target.dataset.filter;
    if (!f) return;
    filter = f;
    filterBar.querySelectorAll(".zn-chip").forEach(function (c) { c.classList.remove("zn-chip-active"); });
    if (f === "custom") document.getElementById("customChip").classList.add("zn-chip-active");
    else e.target.classList.add("zn-chip-active");
    renderLeaderboard();
  });
  customN.addEventListener("input", function () {
    filter = "custom";
    filterBar.querySelectorAll(".zn-chip").forEach(function (c) { c.classList.remove("zn-chip-active"); });
    document.getElementById("customChip").classList.add("zn-chip-active");
    renderLeaderboard();
  });

  function updateCell(teamId, field, value) {
    var t = teams.find(function (x) { return x.id === teamId; });
    if (!t) return;
    if (field === "name") {
      t.name = value;
    } else if (field === "members") {
      t.membersRaw = value; // keep exactly what is typed so commas/spaces are not wiped mid-typing
      t.members = value.split(",").map(function (m) { return m.trim(); }).filter(Boolean);
    } else if (ROUND_KEYS.indexOf(field) !== -1) {
      t.marks[field] = value === "" ? 0 : Number(value);
    }
    renderLeaderboard(true);
    refreshAnalytics();
  }

  function removeTeam(id) {
    teams = teams.filter(function (t) { return t.id !== id; });
    renderLeaderboard();
    renderFaceoffOptions();
    refreshAnalytics();
  }

  document.getElementById("addRowBtn").addEventListener("click", function () {
    teams.push({ id: uid(), name: "New Team", members: [], marks: { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 } });
    renderLeaderboard();
    renderFaceoffOptions();
    refreshAnalytics();
  });

  function renderLeaderboard(preserveFocus) {
    var body = document.getElementById("leaderboardBody");
    var focusInfo = null;
    var active = document.activeElement;
    if (preserveFocus && active && active.dataset && active.dataset.team) {
      var ss = null;
      try { ss = active.selectionStart; } catch (e) { ss = active.value ? active.value.length : 0; }
      focusInfo = { id: active.dataset.team, field: active.dataset.field, selStart: ss };
    }

    var r = ranked();
    var visible = r;
    if (filter === "5") visible = r.slice(0, 5);
    else if (filter === "10") visible = r.slice(0, 10);
    else if (filter === "custom") visible = r.slice(0, Math.max(1, Number(customN.value) || 1));

    if (visible.length === 0) {
      body.innerHTML = '<tr><td colspan="10" class="zn-empty">No teams yet — upload a file or use "+ Add Team".</td></tr>';
      renderFaceoffOptions();
      return;
    }

    body.innerHTML = visible.map(function (t) {
      var podiumClass = t.rank <= 3 ? " zn-row-podium zn-podium-" + t.rank : "";
      var roundsHtml = ROUND_KEYS.map(function (k) {
        return '<td class="zn-col-round"><input type="text" inputmode="numeric" pattern="[0-9]*" class="zn-markinput" data-team="' + esc(t.id) + '" data-field="' + k + '" value="' + (t.marks[k] === "" ? "" : t.marks[k]) + '"></td>';
      }).join("");
      return '<tr class="' + podiumClass + '">' +
        '<td class="zn-col-rank"><span class="zn-rankbadge">' + t.rank + '</span></td>' +
        '<td><input type="text" class="zn-nameinput" data-team="' + esc(t.id) + '" data-field="name" value="' + esc(t.name) + '"></td>' +
        '<td><input type="text" class="zn-membersinput" data-team="' + esc(t.id) + '" data-field="members" value="' + esc(t.membersRaw !== undefined ? t.membersRaw : t.members.join(", ")) + '" placeholder="comma separated"></td>' +
        roundsHtml +
        '<td class="zn-col-total"><strong>' + t.total + '</strong></td>' +
        '<td class="zn-col-remove"><button class="zn-rowremove" data-remove="' + esc(t.id) + '" title="Remove team">&#10005;</button></td>' +
        '</tr>';
    }).join("");

    body.querySelectorAll("input[data-team]").forEach(function (inp) {
      inp.addEventListener("input", function () {
        if (inp.classList.contains("zn-markinput")) {
          var cleaned = inp.value.replace(/[^0-9]/g, "");
          if (cleaned !== inp.value) {
            var pos = inp.selectionStart - (inp.value.length - cleaned.length);
            inp.value = cleaned;
            try { inp.setSelectionRange(pos, pos); } catch (e) {}
          }
        }
        updateCell(inp.dataset.team, inp.dataset.field, inp.value);
      });
    });
    body.querySelectorAll("[data-remove]").forEach(function (btn) {
      btn.addEventListener("click", function () { removeTeam(btn.dataset.remove); });
    });

    if (focusInfo) {
      var el = body.querySelector('input[data-team="' + CSS.escape(focusInfo.id) + '"][data-field="' + focusInfo.field + '"]');
      if (el) {
        el.focus();
        try { el.setSelectionRange(focusInfo.selStart, focusInfo.selStart); } catch (e) {}
      }
    }

    renderFaceoffOptions();
  }

  // ---------- File upload: Excel / CSV ----------
  var uploadStatus = document.getElementById("uploadStatus");
  var DEFAULT_STATUS = 'Expected columns: Team Name, Members, and points (Round 1–5 or a single Points column).';

  function showUploadStatus(msg, kind) {
    uploadStatus.textContent = msg;
    uploadStatus.className = "zn-uploadstatus" + (kind === "ok" ? " zn-status-ok" : kind === "err" ? " zn-status-err" : "");
  }

  function detectHeader(row) {
    var lower = row.map(function (c) { return String(c == null ? "" : c).toLowerCase().trim(); });
    var teamIdx = lower.findIndex(function (c) { return c.indexOf("team") !== -1; });
    if (teamIdx === -1) return null;
    var membersIdx = lower.findIndex(function (c) { return c.indexOf("member") !== -1 || c.indexOf("player") !== -1; });
    var rounds = {};
    lower.forEach(function (c, i) {
      var m = c.match(/round\s*([1-5])/);
      if (m) rounds["r" + m[1]] = i;
    });
    var usedIdx = [teamIdx, membersIdx].concat(Object.keys(rounds).map(function (k) { return rounds[k]; }));
    var pointsIdx = [];
    lower.forEach(function (c, i) {
      if (usedIdx.indexOf(i) !== -1) return;
      if (c.indexOf("point") !== -1 || c.indexOf("mark") !== -1 || c.indexOf("score") !== -1) pointsIdx.push(i);
    });
    if (Object.keys(rounds).length === 0 && pointsIdx.length === 0) return null;
    return {
      team: teamIdx,
      members: membersIdx === -1 ? null : membersIdx,
      rounds: Object.keys(rounds).length ? rounds : null,
      points: pointsIdx.length ? pointsIdx : null
    };
  }

  function importRows(rawRows, sourceLabel) {
    var rows = rawRows.filter(function (r) { return r && r.some(function (c) { return String(c == null ? "" : c).trim() !== ""; }); });
    if (!rows.length) { showUploadStatus("No data found in that file.", "err"); return; }

    var colMap = null, headerIdx = -1;
    for (var i = 0; i < Math.min(rows.length, 8); i++) {
      var map = detectHeader(rows[i]);
      if (map) { headerIdx = i; colMap = map; break; }
    }

    var dataRows;
    if (colMap) {
      dataRows = rows.slice(headerIdx + 1);
    } else {
      colMap = { team: 0, members: 1, rounds: null, points: [2, 3, 4, 5, 6] };
      dataRows = rows;
    }

    var newTeams = [];
    dataRows.forEach(function (r) {
      var name = String(colMap.team != null ? (r[colMap.team] == null ? "" : r[colMap.team]) : "").trim();
      if (!name) return;
      var membersRaw = colMap.members != null ? String(r[colMap.members] == null ? "" : r[colMap.members]) : "";
      var members = membersRaw.split(/[,;]/).map(function (m) { return m.trim(); }).filter(Boolean);
      var marks = { r1: 0, r2: 0, r3: 0, r4: 0, r5: 0 };
      if (colMap.rounds) {
        Object.keys(colMap.rounds).forEach(function (rk) {
          var v = Number(r[colMap.rounds[rk]]);
          marks[rk] = isNaN(v) ? 0 : v;
        });
      } else if (colMap.points) {
        var vals = colMap.points
          .filter(function (idx) { return idx < r.length; })
          .map(function (idx) { var v = Number(r[idx]); return isNaN(v) ? null : v; })
          .filter(function (v) { return v !== null; });
        ROUND_KEYS.forEach(function (rk, i) { marks[rk] = vals[i] !== undefined ? vals[i] : 0; });
      }
      newTeams.push({ id: uid(), name: name, members: members, marks: marks });
    });

    if (!newTeams.length) { showUploadStatus("Couldn't find any team rows in that file.", "err"); return; }

    teams = newTeams.slice(0, 50);
    renderLeaderboard();
    refreshAnalytics();
    setSyncLabel("Loaded " + teams.length + " teams from " + sourceLabel, true);
    showUploadStatus("Loaded " + teams.length + " teams — edit any cell if something looks off.", "ok");
  }

  document.getElementById("excelInput").addEventListener("change", function (e) {
    var file = e.target.files[0];
    if (!file) return;
    showUploadStatus("Reading " + file.name + "…");
    var reader = new FileReader();
    reader.onload = function (ev) {
      try {
        var data = new Uint8Array(ev.target.result);
        var wb = XLSX.read(data, { type: "array" });
        var ws = wb.Sheets[wb.SheetNames[0]];
        var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "" });
        importRows(rows, "your Excel file");
      } catch (err) {
        showUploadStatus("Couldn't read that Excel file.", "err");
      }
    };
    reader.onerror = function () { showUploadStatus("Couldn't read that file.", "err"); };
    reader.readAsArrayBuffer(file);
    e.target.value = "";
  });

  // ---------- File upload: PDF (best-effort text table parsing) ----------
  if (window.pdfjsLib) {
    pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
  }

  document.getElementById("pdfInput").addEventListener("change", function (e) {
    var file = e.target.files[0];
    if (!file) return;
    showUploadStatus("Reading " + file.name + "… (PDF tables work best when kept simple)");
    var reader = new FileReader();
    reader.onload = function (ev) {
      var typedarray = new Uint8Array(ev.target.result);
      if (!window.pdfjsLib) { showUploadStatus("PDF reader failed to load.", "err"); return; }
      pdfjsLib.getDocument({ data: typedarray }).promise.then(function (pdf) {
        var pagePromises = [];
        for (var p = 1; p <= pdf.numPages; p++) {
          pagePromises.push(pdf.getPage(p).then(function (page) {
            return page.getTextContent().then(function (tc) {
              var lines = {};
              tc.items.forEach(function (it) {
                var y = Math.round(it.transform[5]);
                if (!lines[y]) lines[y] = [];
                lines[y].push(it);
              });
              var ys = Object.keys(lines).map(Number).sort(function (a, b) { return b - a; });
              return ys.map(function (y) {
                return lines[y]
                  .sort(function (a, b) { return a.transform[4] - b.transform[4]; })
                  .map(function (it) { return it.str; })
                  .join(" ");
              });
            });
          }));
        }
        return Promise.all(pagePromises);
      }).then(function (pagesLines) {
        var allLines = [].concat.apply([], pagesLines).filter(function (l) { return l.trim() !== ""; });
        var rows = allLines.map(function (l) {
          return l.split(/\s{2,}|\t|,/).map(function (s) { return s.trim(); }).filter(function (s) { return s !== ""; });
        });
        importRows(rows, "your PDF");
      }).catch(function () {
        showUploadStatus("Couldn't read that PDF — try a simpler table layout.", "err");
      });
    };
    reader.onerror = function () { showUploadStatus("Couldn't read that file.", "err"); };
    reader.readAsArrayBuffer(file);
    e.target.value = "";
  });

  // ---------- Faceoff ----------
  var faceA = document.getElementById("faceA");
  var faceB = document.getElementById("faceB");
  var faceRound = document.getElementById("faceRound");
  var arenaWrap = document.getElementById("arenaWrap");

  function renderFaceoffOptions() {
    [faceA, faceB].forEach(function (sel, idx) {
      var current = sel.value;
      var otherVal = idx === 0 ? faceB.value : faceA.value;
      sel.innerHTML = '<option value="">Select team ' + (idx === 0 ? "A" : "B") + '</option>' +
        teams.map(function (t) {
          return '<option value="' + esc(t.id) + '"' + (t.id === otherVal ? " disabled" : "") + '>' + esc(t.name) + '</option>';
        }).join("");
      if (teams.some(function (t) { return t.id === current; })) sel.value = current;
    });
  }

  document.getElementById("startBattleBtn").addEventListener("click", function () {
    var a = teams.find(function (t) { return t.id === faceA.value; });
    var b = teams.find(function (t) { return t.id === faceB.value; });
    if (!a || !b || a.id === b.id) return;
    var roundLabel = ROUND_LABELS[faceRound.value];

    function memberList(team) {
      if (!team.members.length) return '<li class="zn-muted">No members listed</li>';
      return team.members.map(function (m, i) {
        return '<li style="animation-delay:' + (0.15 + i * 0.1) + 's">' + esc(m) + '</li>';
      }).join("");
    }

    arenaWrap.innerHTML =
      '<div class="zn-arena">' +
        '<div class="zn-arena-roundtag">' + esc(roundLabel) + '</div>' +
        '<div class="zn-arena-grid">' +
          '<div class="zn-teampanel zn-teampanel-left"><h3>' + esc(a.name) + '</h3><ul>' + memberList(a) + '</ul></div>' +
          '<div class="zn-vs-badge"><span class="zn-vs-bolt zn-vs-bolt-l">&#9889;</span>VS<span class="zn-vs-bolt zn-vs-bolt-r">&#9889;</span></div>' +
          '<div class="zn-teampanel zn-teampanel-right"><h3>' + esc(b.name) + '</h3><ul>' + memberList(b) + '</ul></div>' +
        '</div>' +
      '</div>';
  });

  // ---------- Reveal (manual slide-through, presentation style) ----------
  var revealEmpty = document.getElementById("revealEmpty");
  var revealSlider = document.getElementById("revealSlider");
  var revealCard = document.getElementById("revealCard");
  var revealRankBig = document.getElementById("revealRankBig");
  var revealNameBig = document.getElementById("revealNameBig");
  var revealPtsBig = document.getElementById("revealPtsBig");
  var revealProgress = document.getElementById("revealProgress");
  var prevRevealBtn = document.getElementById("prevRevealBtn");
  var nextRevealBtn = document.getElementById("nextRevealBtn");
  var qualifyN = document.getElementById("qualifyN");

  var revealOrder = [];   // lowest qualifying rank first, best team last
  var revealIndex = 0;    // which slide is showing
  var revealedUpTo = -1;  // highest index revealed so far

  function renderRevealSlide() {
    var t = revealOrder[revealIndex];
    var isRevealed = revealIndex <= revealedUpTo;
    revealRankBig.textContent = "#" + t.rank;
    revealNameBig.textContent = t.name;
    revealPtsBig.textContent = t.total + " pts";
    revealCard.classList.toggle("zn-flipped", isRevealed);
    prevRevealBtn.disabled = revealIndex === 0;
    nextRevealBtn.disabled = !isRevealed || revealIndex === revealOrder.length - 1;
    revealProgress.textContent = (revealIndex + 1) + " / " + revealOrder.length +
      (revealIndex === revealOrder.length - 1 && isRevealed ? " — that's the lineup!" : "");
  }

  document.getElementById("startRevealBtn").addEventListener("click", function () {
    var r = ranked();
    var n = Math.max(1, Math.min(Number(qualifyN.value) || 1, r.length));
    revealOrder = r.slice(0, n).slice().reverse();
    revealIndex = 0;
    revealedUpTo = -1;
    revealEmpty.style.display = "none";
    revealSlider.style.display = "flex";
    renderRevealSlide();
  });

  document.getElementById("resetRevealBtn").addEventListener("click", function () {
    revealOrder = [];
    revealIndex = 0;
    revealedUpTo = -1;
    revealSlider.style.display = "none";
    revealEmpty.style.display = "block";
  });

  document.getElementById("revealSquare").addEventListener("click", function () {
    if (!revealOrder.length) return;
    if (revealIndex > revealedUpTo) revealedUpTo = revealIndex;
    renderRevealSlide();
  });

  nextRevealBtn.addEventListener("click", function () {
    if (revealIndex < revealOrder.length - 1 && revealIndex <= revealedUpTo) {
      revealIndex += 1;
      renderRevealSlide();
    }
  });

  prevRevealBtn.addEventListener("click", function () {
    if (revealIndex > 0) {
      revealIndex -= 1;
      renderRevealSlide();
    }
  });

  // ---------- Gallery ----------
  var galleryItems = []; // { id, type: 'image'|'video', url, name }
  var galleryGrid = document.getElementById("galleryGrid");
  var galleryEmpty = document.getElementById("galleryEmpty");
  var galleryInput = document.getElementById("galleryInput");
  var lightbox = document.getElementById("lightbox");
  var lightboxStage = document.getElementById("lightboxStage");
  var lightboxClose = document.getElementById("lightboxClose");
  var lightboxFs = document.getElementById("lightboxFs");
  var lightboxPrev = document.getElementById("lightboxPrev");
  var lightboxNext = document.getElementById("lightboxNext");
  var lightboxIndex = 0;

  function renderGallery() {
    if (!galleryItems.length) {
      galleryEmpty.style.display = "block";
      galleryGrid.innerHTML = "";
      return;
    }
    galleryEmpty.style.display = "none";
    galleryGrid.innerHTML = galleryItems.map(function (item, i) {
      var media = item.type === "video"
        ? '<video src="' + item.url + '" muted playsinline preload="metadata"></video>'
        : '<img src="' + item.url + '" alt="' + esc(item.name) + '" loading="lazy">';
      var badge = item.type === "video" ? '<span class="zn-gallery-badge">VIDEO</span>' : "";
      return '<div class="zn-gallerytile" data-index="' + i + '">' +
        media +
        badge +
        '<div class="zn-gallery-overlay">&#128269;</div>' +
        '<button class="zn-gallery-remove" data-remove-gallery="' + esc(item.id) + '" title="Remove">&#10005;</button>' +
        '</div>';
    }).join("");

    galleryGrid.querySelectorAll(".zn-gallerytile").forEach(function (tile) {
      tile.addEventListener("click", function (e) {
        if (e.target.closest("[data-remove-gallery]")) return;
        openLightbox(Number(tile.dataset.index));
      });
    });
    galleryGrid.querySelectorAll("[data-remove-gallery]").forEach(function (btn) {
      btn.addEventListener("click", function (e) {
        e.stopPropagation();
        galleryItems = galleryItems.filter(function (g) { return g.id !== btn.dataset.removeGallery; });
        renderGallery();
      });
    });
  }

  galleryInput.addEventListener("change", function (e) {
    var files = Array.prototype.slice.call(e.target.files || []);
    files.forEach(function (file) {
      var isVideo = file.type.indexOf("video") === 0;
      var isImage = file.type.indexOf("image") === 0;
      if (!isVideo && !isImage) return;
      var reader = new FileReader();
      reader.onload = function (ev) {
        galleryItems.push({ id: uid(), type: isVideo ? "video" : "image", url: ev.target.result, name: file.name });
        renderGallery();
      };
      reader.readAsDataURL(file);
    });
    e.target.value = "";
  });

  function openLightbox(index) {
    lightboxIndex = index;
    renderLightbox();
    lightbox.classList.add("zn-lightbox-open");
  }

  function renderLightbox() {
    var item = galleryItems[lightboxIndex];
    if (!item) { closeLightbox(); return; }
    lightboxStage.innerHTML = item.type === "video"
      ? '<video src="' + item.url + '" controls autoplay playsinline></video>'
      : '<img src="' + item.url + '" alt="' + esc(item.name) + '">';
    lightboxPrev.disabled = lightboxIndex === 0;
    lightboxNext.disabled = lightboxIndex === galleryItems.length - 1;
  }

  function closeLightbox() {
    lightbox.classList.remove("zn-lightbox-open");
    lightboxStage.innerHTML = "";
    if (document.fullscreenElement) document.exitFullscreen();
  }

  lightboxClose.addEventListener("click", closeLightbox);
  lightbox.addEventListener("click", function (e) {
    if (e.target === lightbox) closeLightbox();
  });
  lightboxPrev.addEventListener("click", function () {
    if (lightboxIndex > 0) { lightboxIndex -= 1; renderLightbox(); }
  });
  lightboxNext.addEventListener("click", function () {
    if (lightboxIndex < galleryItems.length - 1) { lightboxIndex += 1; renderLightbox(); }
  });
  lightboxFs.addEventListener("click", function () {
    if (!document.fullscreenElement) {
      var el = lightboxStage.firstElementChild || lightboxStage;
      if (el.requestFullscreen) el.requestFullscreen();
    } else if (document.exitFullscreen) {
      document.exitFullscreen();
    }
  });
  document.addEventListener("keydown", function (e) {
    if (!lightbox.classList.contains("zn-lightbox-open")) return;
    if (e.key === "Escape") closeLightbox();
    if (e.key === "ArrowLeft") lightboxPrev.click();
    if (e.key === "ArrowRight") lightboxNext.click();
  });

  // ---------- Analytics ----------
  var RACE_ROW_H = 48;
  var raceStage = document.getElementById("raceStage");
  var bubbleStage = document.getElementById("bubbleStage");
  var raceControls = document.getElementById("raceControls");
  var raceScrubber = document.getElementById("raceScrubber");
  var raceRoundLabel = document.getElementById("raceRoundLabel");
  var racePlayBtn = document.getElementById("racePlayBtn");
  var raceRows = {};
  var currentRaceRound = 5;
  var racePlaying = false;
  var raceTimer = null;
  var analyticsView = "race";

  function hashStr(s) {
    var h = 0;
    for (var i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; }
    return Math.abs(h);
  }
  function teamColor(id) {
    var h = hashStr(String(id));
    var hue = (330 + (h % 90)) % 360;
    var light = 52 + (h % 18);
    return "hsl(" + hue + ", 62%, " + light + "%)";
  }

  function raceCumulative(team, uptoRound) {
    var s = 0;
    for (var i = 1; i <= uptoRound; i++) { s += Number(team.marks["r" + i]) || 0; }
    return s;
  }

  function ensureRaceRow(team) {
    if (raceRows[team.id]) return raceRows[team.id];
    var row = document.createElement("div");
    row.className = "zn-racerow";
    row.innerHTML = '<div class="zn-racebar-track"><div class="zn-racebar"><span class="zn-racebar-name"></span></div><span class="zn-racebar-value"></span></div>';
    raceStage.appendChild(row);
    var obj = { el: row, bar: row.querySelector(".zn-racebar"), name: row.querySelector(".zn-racebar-name"), val: row.querySelector(".zn-racebar-value") };
    raceRows[team.id] = obj;
    return obj;
  }

  function renderRace(round) {
    currentRaceRound = round;
    if (!teams.length) {
      raceStage.innerHTML = '<p class="zn-empty">No teams yet.</p>';
      raceRows = {};
      return;
    }
    var globalMax = 0;
    teams.forEach(function (t) { var tot = raceCumulative(t, 5); if (tot > globalMax) globalMax = tot; });
    if (globalMax <= 0) globalMax = 1;

    var withVals = teams.map(function (t) { return { t: t, val: raceCumulative(t, round) }; });
    withVals.sort(function (a, b) { return b.val - a.val; });

    raceStage.style.height = (withVals.length * RACE_ROW_H + 8) + "px";

    withVals.forEach(function (item, idx) {
      var row = ensureRaceRow(item.t);
      row.el.style.top = (idx * RACE_ROW_H) + "px";
      var pct = Math.max(3, (item.val / globalMax) * 100);
      row.bar.style.width = pct + "%";
      row.bar.style.background = teamColor(item.t.id);
      row.name.textContent = item.t.name;
      row.val.textContent = item.val;
    });

    Object.keys(raceRows).forEach(function (id) {
      if (!teams.some(function (t) { return t.id === id; })) {
        raceRows[id].el.remove();
        delete raceRows[id];
      }
    });

    raceRoundLabel.textContent = "Through Round " + round;
    raceScrubber.value = round;
  }

  function raceTick() {
    var next = currentRaceRound + 1;
    if (next > 5) next = 1;
    renderRace(next);
  }

  racePlayBtn.addEventListener("click", function () {
    racePlaying = !racePlaying;
    if (racePlaying) {
      racePlayBtn.innerHTML = "&#10074;&#10074; Pause";
      raceTimer = setInterval(raceTick, 1500);
    } else {
      racePlayBtn.innerHTML = "&#9654; Play";
      clearInterval(raceTimer);
    }
  });

  document.getElementById("raceResetBtn").addEventListener("click", function () {
    racePlaying = false;
    clearInterval(raceTimer);
    racePlayBtn.innerHTML = "&#9654; Play";
    renderRace(1);
  });

  raceScrubber.addEventListener("input", function () {
    racePlaying = false;
    clearInterval(raceTimer);
    racePlayBtn.innerHTML = "&#9654; Play";
    renderRace(Number(raceScrubber.value));
  });

  function renderBubbles() {
    var r = ranked();
    if (!r.length) {
      bubbleStage.innerHTML = '<p class="zn-empty">No teams yet.</p>';
      return;
    }
    var maxTotal = Math.max.apply(null, r.map(function (t) { return t.total; }).concat([1]));
    var w = bubbleStage.clientWidth || 600;
    var h = bubbleStage.clientHeight || 420;
    bubbleStage.innerHTML = "";
    r.forEach(function (t) {
      var size = 46 + (t.total / maxTotal) * 90;
      var left = Math.random() * Math.max(1, w - size);
      var top = Math.random() * Math.max(1, h - size);
      var dur = (5 + Math.random() * 4).toFixed(1) + "s";
      var delay = (Math.random() * 3).toFixed(1) + "s";
      var b = document.createElement("div");
      b.className = "zn-bubble";
      b.style.width = size + "px";
      b.style.height = size + "px";
      b.style.left = left + "px";
      b.style.top = top + "px";
      b.style.background = teamColor(t.id);
      b.style.setProperty("--dur", dur);
      b.style.setProperty("--delay", delay);
      b.innerHTML = "<span>" + esc(t.name) + "</span><span class=\"zn-bubble-pts\">" + t.total + " pts</span>";
      bubbleStage.appendChild(b);
    });
  }

  function refreshAnalytics() {
    if (analyticsView === "race") renderRace(currentRaceRound);
    else renderBubbles();
  }

  document.getElementById("analyticsToggle").addEventListener("click", function (e) {
    var view = e.target.dataset.view;
    if (!view) return;
    analyticsView = view;
    document.querySelectorAll("#analyticsToggle .zn-chip").forEach(function (c) { c.classList.remove("zn-chip-active"); });
    e.target.classList.add("zn-chip-active");
    if (view === "race") {
      raceControls.style.display = "flex";
      raceStage.style.display = "block";
      bubbleStage.style.display = "none";
      renderRace(currentRaceRound);
    } else {
      raceControls.style.display = "none";
      raceStage.style.display = "none";
      bubbleStage.style.display = "block";
      renderBubbles();
    }
  });

  document.querySelector('.zn-tab[data-tab="analytics"]').addEventListener("click", refreshAnalytics);


  var AVATAR_DATA_URI = "data:image/jpeg;base64,";
  var cvAvatar = document.getElementById("cvAvatar");
  if (cvAvatar) cvAvatar.src = AVATAR_DATA_URI;

  // ---------- Social links (edit these two URLs) ----------
  var SOCIAL_LINKS = {
    linkedin: "https://www.linkedin.com/in/vansh-kirar-675809349/",
    github: "https://github.com/VanshKirar1315",
    email: "mailto:vanshkirar2005@gmail.com"
  };
  document.querySelectorAll('[data-social]').forEach(function (el) {
    var url = SOCIAL_LINKS[el.dataset.social];
    if (url && url !== "#") el.href = url;
  });

  // ---------- Theme (dark / light) ----------
  var themeToggle = document.getElementById("themeToggle");
  if (themeToggle) {
    themeToggle.addEventListener("click", function () {
      var root = document.documentElement;
      var next = root.getAttribute("data-theme") === "light" ? "dark" : "light";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem("zenith-theme", next); } catch (e) {}
    });
  }

  // ---------- Init ----------
  renderLeaderboard();
  renderGallery();
  renderRace(5);
})();
